```js
const selectedBoardItems = new Map();
const selectionCtrl = new AbortController();
await document.modelContext.registerTool(
  {
    name: 'get_selected_items',
    description: 'Returns up to 10 issues, bugs, and epics currently selected on the project board. Use when the user asks about selected items before calling move_items.',
    inputSchema: { type: 'object', properties: {} },
    outputSchema: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string', description: 'Item ID passed to move_items' },
          type: { type: 'string', enum: ['issue', 'bug', 'epic'] },
          sprint_id: { type: 'string', description: 'Assigned sprint ID' },
          blocked_by_ids: { type: 'array', items: { type: 'string' } },
          priority: { type: 'string', enum: ['p0', 'p1', 'p2'] }
        },
        required: ['id', 'type', 'sprint_id', 'blocked_by_ids', 'priority']
      }
    },
    annotations: { readOnlyHint: true },
    execute() {
      return Array.from(selectedBoardItems.values()).slice(0, 10);
    }
  },
  { signal: selectionCtrl.signal }
);

const commentsCtrl = new AbortController();
await document.modelContext.registerTool(
  {
    name: 'list_issue_comments',
    description: 'Lists comments posted by users on an issue. Use when the user wants to read discussion threads on a specific issue.',
    inputSchema: {
      type: 'object',
      properties: { issue_id: { type: 'string', description: 'Issue identifier' } },
      required: ['issue_id']
    },
    outputSchema: {
      type: 'object',
      properties: {
        total_count: { type: 'integer' },
        comments: {
          type: 'array',
          items: {
            type: 'object',
            properties: { author: { type: 'string' }, body: { type: 'string' } },
            required: ['author', 'body']
          }
        }
      },
      required: ['total_count', 'comments']
    },
    annotations: { readOnlyHint: true, destructiveHint: false, idempotentHint: true },
    async execute({ issue_id }, { signal }) {
      const res = await fetch(`/api/issues/${encodeURIComponent(issue_id)}/comments`, { signal });
      if (!res.ok) throw new Error('Issue not found');
      const data = await res.json();
      return {
        structuredContent: { total_count: data.total, comments: data.items },
        content: [{ type: 'text', text: JSON.stringify(data.items) }]
      };
    }
  },
  { signal: commentsCtrl.signal }
);
```

