1. `search_catalog`:
```js
const ctrl1 = new AbortController();
await document.modelContext.registerTool({
  name: 'search_catalog',
  description: 'Searches the product catalog by keyword. Use when the user wants to browse products before adding an item to the cart.',
  inputSchema: { type: 'object', properties: { query: { type: 'string', description: 'Search terms' } }, required: ['query'] },
  outputSchema: {
    type: 'object',
    properties: {
      total_count: { type: 'integer' },
      items: { type: 'array', items: { type: 'object', properties: { product_id: { type: 'string' }, price: { type: 'number' } }, required: ['product_id', 'price'] } }
    },
    required: ['total_count', 'items']
  },
  annotations: { readOnlyHint: true },
  async execute({ query }, { signal }) {
    const res = await fetch(`/api/catalog?q=${encodeURIComponent(query)}`, { signal });
    if (!res.ok) return { error: 'Catalog unavailable. Please retry shortly.', retryable: true };
    return await res.json();
  }
}, { signal: ctrl1.signal });
```
